_ABSOLUTE_ZERO = {"C": -273.15, "F": -459.67, "K": 0.0}


def _to_celsius(value, unit):
    if unit == "C":
        return value
    if unit == "F":
        return (value - 32) * 5 / 9
    return value - 273.15


def _from_celsius(value, unit):
    if unit == "C":
        return value
    if unit == "F":
        return value * 9 / 5 + 32
    return value + 273.15


def convert(value, source, target):
    """Converts a temperature between Celsius (C), Fahrenheit (F) and Kelvin (K).

    Raises ValueError for unknown units or values below absolute zero.
    """
    for unit in (source, target):
        if unit not in _ABSOLUTE_ZERO:
            raise ValueError(f"unknown unit {unit!r}")
    if value < _ABSOLUTE_ZERO[source]:
        raise ValueError(f"{value} {source} is below absolute zero")
    if source == target:
        return value
    return _from_celsius(_to_celsius(value, source), target)

